const body = $json.body ?? $json;
const text = v => (v ?? '').toString().trim();
const lead = {
  company_name: text(body.company_name),
  company_type: text(body.company_type || 'نامشخص'),
  contact_name: text(body.contact_name),
  job_title: text(body.job_title),
  phone: text(body.phone),
  email: text(body.email).toLowerCase(),
  city: text(body.city),
  province: text(body.province),
  lead_source: text(body.lead_source || 'webhook'),
  project_type: text(body.project_type),
  estimated_units: Number(body.estimated_units || 0),
  project_stage: text(body.project_stage),
  need_description: text(body.need_description),
  consent_status: text(body.consent_status || 'unknown'),
  consent_source: text(body.consent_source),
  created_at: new Date().toISOString(),
  lead_status: 'new'
};
let score = 0;
if (lead.company_name) score += 10;
if (lead.phone || lead.email) score += 15;
if (['انبوه‌ساز','انبوه ساز','سازنده','پیمانکار','شرکت نصب'].includes(lead.company_type)) score += 20;
if (lead.project_type) score += 10;
if (lead.estimated_units >= 2) score += 10;
if (lead.project_stage && !['نامشخص',''].includes(lead.project_stage)) score += 10;
if (lead.need_description) score += 5;
if (lead.consent_status === 'yes' || lead.consent_status === 'documented') score += 10;
lead.lead_score = Math.min(score,100);
lead.priority = lead.lead_score >= 60 ? 'high' : lead.lead_score >= 35 ? 'medium' : 'low';
lead.validation_errors = [];
if (!lead.company_name) lead.validation_errors.push('company_name_missing');
if (!lead.phone && !lead.email) lead.validation_errors.push('contact_channel_missing');
lead.ready_for_outreach = lead.validation_errors.length === 0 && ['yes','documented'].includes(lead.consent_status);
return [{json:lead}];
